using System;

// PROGRAM: Penerapan Pattern Matching Modern pada Evaluasi Transaksi Finansial
public record Transaction(string Type, decimal Amount, bool IsSuspicious);

public class FraudDetectionEngine
{
    public static string EvaluateTransaction(Transaction tx) => tx switch
    {
        // 1. Transaksi berapapun jika mencurigakan -> BLOKIR SEGERA
        { IsSuspicious: true } => "BLOCKED: Terdeteksi Pola Fraud!",

        // 2. Penarikan tunai di atas 50 juta -> Butuh Verifikasi Tambahan
        { Type: "Withdrawal", Amount: > 50_000_000m } => "REVIEW: Butuh Otorisasi Kepala Cabang",

        // 3. Transfer normal di bawah 100 juta -> Otomatis Setuju
        { Type: "Transfer", Amount: <= 100_000_000m } => "APPROVED: Transaksi Diproses Otomatis",

        // 4. Default fallback
        _ => "PENDING: Sedang Diverifikasi Sistem Antrian"
    };
}

public class Program
{
    public static void Main()
    {
        var tx1 = new Transaction("Transfer", 15_000_000m, false);
        var tx2 = new Transaction("Withdrawal", 75_000_000m, false);
        var tx3 = new Transaction("Transfer", 5_000_000m, true);

        Console.WriteLine($"Tx 1: {FraudDetectionEngine.EvaluateTransaction(tx1)}");
        Console.WriteLine($"Tx 2: {FraudDetectionEngine.EvaluateTransaction(tx2)}");
        Console.WriteLine($"Tx 3: {FraudDetectionEngine.EvaluateTransaction(tx3)}");
    }
}

