using System;

public class TaxCalculator
{
    public static int GetTaxRatePercentage(decimal annualIncome) => annualIncome switch
    {
        <= 0m => 0,
        <= 60_000_000m => 5,
        > 60_000_000m and <= 250_000_000m => 15,
        > 250_000_000m and <= 500_000_000m => 25,
        _ => 30
    };

    public static void Main()
    {
        Console.WriteLine($"50 Juta : {GetTaxRatePercentage(50_000_000m)}%");
        Console.WriteLine($"100 Juta: {GetTaxRatePercentage(100_000_000m)}%");
        Console.WriteLine($"600 Juta: {GetTaxRatePercentage(600_000_000m)}%");
    }
}
